float sdHeart( in vec2 p )
{
    p.x = abs(p.x);

    if( p.y+p.x>1.0 )
        return sqrt(dot2(p-vec2(0.25,0.75))) - sqrt(2.0)/4.0;
    return sqrt(min(dot2(p-vec2(0.00,1.00)),
                    dot2(p-0.5*max(p.x+p.y,0.0)))) * sign(p.x-p.y);
}

void mainImage( out vec4 c, in vec2 u )
{
    vec2 p = (u*2.0-iResolution.xy)/iResolution.y;
    p.y += 0.5;
    float a = min(0.05,max(0.,cos(iTime)));
    p += (sin(iTime * vec2(20.,15.)) * vec2(0.3,0.2)) * a;
    float t = min(0.05,max(0.,cos(iTime)));
    vec2 suv = p;
    suv.y += iTime*0.2; 
    suv.x += mix(0.,cos( 1.4 + min(fract(suv.y * 10.),1.-fract(suv.y * 10.))  )*0.25 , smoothstep(0.35,0.0,length(p-vec2(0.,0.5)) - 0.2));
    float split = abs(suv.x) - t;
    split = mix(1.,split,clamp(t*100.,0.,1.));
    float Heart = sdHeart(vec2(abs(p.x)-t,p.y));
    float d = min(smoothstep(0.02,0.0,Heart), smoothstep(0.0,0.05,split));
    vec3 col = pow(abs(d)/0.3,1.3) * vec3(0.8,0.2,0.2);
    c = vec4(col,1.0);
}
